<script setup lang="ts">
import { computed, ref } from 'vue'
import { ElButton, ElButtonGroup, ElDialog, ElForm, ElFormItem, ElInput, ElOption, ElSelect, ElTable, ElTableColumn, ElTag } from 'element-plus'
type Transaction = { id: string; title: string; category: string; type: '收入' | '支出'; amount: number; date: string }
const storageKey = 'ikaros-console-finance-transactions'; const read = (): Transaction[] => { try { const value = JSON.parse(localStorage.getItem(storageKey) || '[]'); return Array.isArray(value) ? value : [] } catch { return [] } }
const transactions = ref<Transaction[]>(read().length ? read() : [{ id: 'demo-1', title: '工资收入', category: '薪资', type: '收入', amount: 12000, date: '今天' }, { id: 'demo-2', title: '云存储订阅', category: '软件服务', type: '支出', amount: 68, date: '昨天' }]); const query = ref(''); const filter = ref('全部'); const dialog = ref(false); const title = ref(''); const category = ref(''); const type = ref<'收入' | '支出'>('支出'); const amount = ref(0); const toast = ref('')
const visible = computed(() => transactions.value.filter(item => (filter.value === '全部' || item.type === filter.value) && `${item.title} ${item.category}`.toLowerCase().includes(query.value.toLowerCase()))); const income = computed(() => transactions.value.filter(item => item.type === '收入').reduce((sum, item) => sum + item.amount, 0)); const expense = computed(() => transactions.value.filter(item => item.type === '支出').reduce((sum, item) => sum + item.amount, 0)); const balance = computed(() => income.value - expense.value)
function notify(message: string) { toast.value = message; window.setTimeout(() => toast.value = '', 2400) }
function save() { localStorage.setItem(storageKey, JSON.stringify(transactions.value)) }
function create() { if (!title.value.trim() || !category.value.trim() || amount.value <= 0) { notify('请填写名称、分类和正数金额'); return } transactions.value.unshift({ id: `local-${Date.now()}`, title: title.value.trim(), category: category.value.trim(), type: type.value, amount: Number(amount.value), date: '刚刚' }); save(); dialog.value = false; title.value = ''; category.value = ''; amount.value = 0; notify('交易已保存到本地账本') }
</script>
<template><div class="finance-shell"><header class="catalog-topbar"><div class="catalog-brand"><span class="brand-mark">i</span><strong>Ikaros <small>Console</small></strong></div><span class="catalog-context">个人记账 · 本地账本</span><span class="mini-avatar">陈</span></header><main class="catalog-main finance-main"><div class="catalog-heading"><div><p class="eyebrow">个人记账</p><h1>账本总览</h1><p>本页数据仅保存在当前浏览器；Finance 数据不会上传或伪装成已同步状态。</p></div><el-button type="primary" @click="dialog = true">＋ 新建交易</el-button></div><nav class="finance-tabs"><RouterLink to="/console/finance" class="active">总览</RouterLink><RouterLink to="/console/finance/accounts">账户</RouterLink><RouterLink to="/console/finance/transactions">交易</RouterLink><RouterLink to="/console/finance/budgets">预算</RouterLink><RouterLink to="/console/finance/reconcile">对账与导入</RouterLink></nav><section class="finance-summary"><article class="surface-card"><span>账本余额</span><strong>¥ {{ balance.toFixed(2) }}</strong><small>收入减支出</small></article><article class="surface-card"><span>收入</span><strong class="finance-income">¥ {{ income.toFixed(2) }}</strong><small>当前本地账本</small></article><article class="surface-card"><span>支出</span><strong class="finance-expense">¥ {{ expense.toFixed(2) }}</strong><small>当前本地账本</small></article></section><div class="finance-toolbar surface-card"><el-input v-model="query" clearable placeholder="搜索交易或分类" style="max-width:360px" /><el-button-group><el-button v-for="value in ['全部','收入','支出']" :key="value" :type="filter === value ? 'primary' : 'default'" @click="filter = value">{{ value }}</el-button></el-button-group></div><section class="finance-table surface-card"><el-table :data="visible" stripe empty-text="没有匹配交易"><el-table-column prop="title" label="交易" min-width="220" /><el-table-column prop="category" label="分类" width="160" /><el-table-column label="类型" width="110"><template #default="{ row }"><el-tag :type="row.type === '收入' ? 'success' : 'warning'">{{ row.type }}</el-tag></template></el-table-column><el-table-column label="金额" width="150"><template #default="{ row }"><span :class="row.type === '收入' ? 'finance-income' : 'finance-expense'">{{ row.type === '收入' ? '+' : '−' }} ¥ {{ row.amount.toFixed(2) }}</span></template></el-table-column><el-table-column prop="date" label="日期" width="140" /></el-table></section></main><el-dialog v-model="dialog" title="新建交易" width="460px"><el-form label-position="top"><el-form-item label="名称 *"><el-input v-model="title" maxlength="160" placeholder="例如：午餐" @keyup.enter="create" /></el-form-item><el-form-item label="分类 *"><el-input v-model="category" maxlength="80" placeholder="例如：餐饮" /></el-form-item><el-form-item label="类型 *"><el-select v-model="type" style="width:100%"><el-option label="支出" value="支出" /><el-option label="收入" value="收入" /></el-select></el-form-item><el-form-item label="金额 *"><el-input v-model.number="amount" type="number" min="0.01" step="0.01" placeholder="0.00" /></el-form-item><p class="account-note">创建后仅写入当前浏览器本地账本；导入/同步和服务端财务 API 尚未启用。</p><div class="dialog-actions"><el-button @click="dialog = false">取消</el-button><el-button type="primary" @click="create">保存交易</el-button></div></el-form></el-dialog><div v-if="toast" class="snackbar">✓ {{ toast }}<button @click="toast = ''">×</button></div></div></template>
